examples.mysql:
SELECT MIN(bucket) AS first_bucket, MAX(bucket) AS last_bucket, COUNT(*) AS n_rows
FROM (
  SELECT NTILE(20) OVER (ORDER BY emp_id) AS bucket
  FROM employees
) t;

